//! Tailwind CSS source discovery for leptos-shadcn-ui.
//!
//! Tailwind v4 only generates utilities for class names it finds in scanned
//! files. Component crates live in the Cargo registry (or a git checkout),
//! outside the application directory Tailwind scans, so their classes are
//! present in the rendered HTML but missing from the compiled CSS.
//!
//! This crate writes a small stylesheet of `@source` directives pointing at
//! every `leptos-shadcn-*` crate in the dependency graph. Call it from the
//! application's `build.rs` and `@import` the generated file from the
//! Tailwind input stylesheet:
//!
//! ```no_run
//! # #![allow(clippy::needless_doctest_main)]
//! // build.rs
//! fn main() {
//!     leptos_shadcn_tailwind::write_sources_css("style/shadcn-sources.css")
//!         .expect("failed to write Tailwind sources for leptos-shadcn-ui");
//! }
//! ```
//!
//! ```css
//! /* style/input.css */
//! @import "tailwindcss";
//! @import "./shadcn-sources.css";
//! ```

use serde_json::Value;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Package name prefixes whose sources contain Tailwind classes.
pub const PACKAGE_PREFIXES: &[&str] = &["leptos-shadcn-"];

/// A dependency whose `src` directory Tailwind should scan.
#[derive(Debug, Clone, PartialEq)]
pub struct ComponentSource {
    /// Cargo package name, e.g. `leptos-shadcn-button`.
    pub name: String,
    /// Absolute path of the package's `src` directory.
    pub src_dir: PathBuf,
}

/// Returns true for package names that ship Tailwind classes.
pub fn is_component_package(name: &str) -> bool {
    name != "leptos-shadcn-tailwind" && PACKAGE_PREFIXES.iter().any(|p| name.starts_with(p))
}

/// Extracts component source directories from `cargo metadata` JSON output.
///
/// Results are sorted by name and de-duplicated, so the generated file is
/// stable across builds.
pub fn sources_from_metadata(metadata_json: &str) -> io::Result<Vec<ComponentSource>> {
    let metadata: Value = serde_json::from_str(metadata_json)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    let packages = metadata
        .get("packages")
        .and_then(Value::as_array)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "metadata has no packages"))?;

    let mut sources: Vec<ComponentSource> = packages
        .iter()
        .filter_map(|pkg| {
            let name = pkg.get("name")?.as_str()?;
            if !is_component_package(name) {
                return None;
            }
            let manifest = Path::new(pkg.get("manifest_path")?.as_str()?);
            Some(ComponentSource {
                name: name.to_string(),
                src_dir: manifest.parent()?.join("src"),
            })
        })
        .collect();
    sources.sort_by(|a, b| a.name.cmp(&b.name).then(a.src_dir.cmp(&b.src_dir)));
    sources.dedup();
    Ok(sources)
}

/// Renders `@source` directives for the given sources.
pub fn render_sources_css(sources: &[ComponentSource]) -> String {
    let mut css = String::from(
        "/* Generated by leptos-shadcn-tailwind. Do not edit. */\n\
         /* Lets Tailwind see the classes used by leptos-shadcn-ui components. */\n",
    );
    for source in sources {
        // Tailwind expects forward slashes, including on Windows.
        let path = source.src_dir.to_string_lossy().replace('\\', "/");
        let path = path.replace('"', "\\\"");
        css.push_str(&format!("@source \"{path}\";\n"));
    }
    css
}

/// Runs `cargo metadata` for the current build and returns component sources.
///
/// Uses the `CARGO` and `CARGO_MANIFEST_DIR` variables Cargo sets for build
/// scripts, falling back to `cargo` and the current directory.
pub fn discover_sources() -> io::Result<Vec<ComponentSource>> {
    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
    let mut cmd = Command::new(cargo);
    cmd.args(["metadata", "--format-version", "1"]);
    if let Ok(dir) = std::env::var("CARGO_MANIFEST_DIR") {
        cmd.current_dir(dir);
    }
    let output = cmd.output()?;
    if !output.status.success() {
        return Err(io::Error::other(format!(
            "cargo metadata failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    sources_from_metadata(&String::from_utf8_lossy(&output.stdout))
}

/// Writes the `@source` stylesheet to `path` (relative paths resolve against
/// `CARGO_MANIFEST_DIR` when set). The file is only rewritten when its
/// contents change, so Tailwind watchers are not retriggered needlessly.
pub fn write_sources_css(path: impl AsRef<Path>) -> io::Result<PathBuf> {
    let path = match std::env::var("CARGO_MANIFEST_DIR") {
        Ok(dir) if path.as_ref().is_relative() => Path::new(&dir).join(path.as_ref()),
        _ => path.as_ref().to_path_buf(),
    };
    let css = render_sources_css(&discover_sources()?);
    if std::fs::read_to_string(&path).ok().as_deref() != Some(css.as_str()) {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&path, css)?;
    }
    println!("cargo:rerun-if-changed=Cargo.toml");
    println!("cargo:rerun-if-changed=Cargo.lock");
    Ok(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    const FIXTURE: &str = include_str!("../tests/fixtures/metadata.json");

    #[test]
    fn filters_component_packages() {
        assert!(is_component_package("leptos-shadcn-button"));
        assert!(!is_component_package("leptos-shadcn-tailwind"));
        assert!(!is_component_package("leptos"));
        assert!(!is_component_package("serde"));
    }

    #[test]
    fn parses_metadata_fixture() {
        let sources = sources_from_metadata(FIXTURE).unwrap();
        let names: Vec<_> = sources.iter().map(|s| s.name.as_str()).collect();
        assert_eq!(
            names,
            [
                "leptos-shadcn-button",
                "leptos-shadcn-card",
                "leptos-shadcn-ui"
            ]
        );
        assert_eq!(
            sources[0].src_dir,
            PathBuf::from(
                "/home/u/.cargo/registry/src/index.crates.io-1/leptos-shadcn-button-0.9.0/src"
            )
        );
    }

    #[test]
    fn renders_source_directives() {
        let css = render_sources_css(&sources_from_metadata(FIXTURE).unwrap());
        assert!(css.contains(
            "@source \"/home/u/.cargo/registry/src/index.crates.io-1/leptos-shadcn-button-0.9.0/src\";"
        ));
        assert_eq!(css.matches("@source").count(), 3);
    }

    #[test]
    fn renders_windows_paths_with_forward_slashes() {
        let css = render_sources_css(&[ComponentSource {
            name: "leptos-shadcn-button".into(),
            src_dir: PathBuf::from(r"C:\Users\u\.cargo\registry\leptos-shadcn-button-0.9.0\src"),
        }]);
        assert!(
            css.contains("@source \"C:/Users/u/.cargo/registry/leptos-shadcn-button-0.9.0/src\";")
        );
    }

    #[test]
    fn rejects_invalid_metadata() {
        assert!(sources_from_metadata("not json").is_err());
        assert!(sources_from_metadata("{}").is_err());
    }
}
